package amm

import (
	"math"
	"math/bits"
	"math/overflow"
)

const bpsDen = int64(10000)

// MulDiv returns floor(a * b / d) for non-negative a, b and d > 0.
// Fast path uses int64 product. Overflow path is 128-bit (a*b)/d — same as
// int64((bigint(a)*bigint(b))/bigint(d)) — and panics only if the quotient
// does not fit int64. Gno has no typed bigint(int64) conversion.
func MulDiv(a, b, d int64) int64 {
	return mulDiv(a, b, d, false)
}

// MulDivCeil is ceil(a * b / d) for non-negative a, b and d > 0.
// Ceil only when remainder != 0.
func MulDivCeil(a, b, d int64) int64 {
	return mulDiv(a, b, d, true)
}

func mulDiv(a, b, d int64, ceil bool) int64 {
	if a < 0 || b < 0 {
		panic("zdex: negative muldiv")
	}
	if d <= 0 {
		panic("zdex: division by zero")
	}
	if a == 0 || b == 0 {
		return 0
	}
	prod, ok := overflow.Mul64(a, b)
	if ok {
		q := prod / d
		if ceil && prod%d != 0 {
			return add64(q, 1)
		}
		return q
	}
	hi, lo := bits.Mul64(uint64(a), uint64(b))
	du := uint64(d)
	if hi >= du {
		panic("zdex: muldiv overflow")
	}
	q, r := bits.Div64(hi, lo, du)
	if ceil && r != 0 {
		if q == uint64(math.MaxInt64) {
			panic("zdex: muldiv overflow")
		}
		q++
	}
	if q > uint64(math.MaxInt64) {
		panic("zdex: muldiv overflow")
	}
	return int64(q)
}

// Sqrt returns floor(sqrt(n)) for n >= 0 (Babylonian method).
func Sqrt(n int64) int64 {
	if n < 0 {
		panic("zdex: sqrt of negative")
	}
	if n < 2 {
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

func add64(a, b int64) int64 {
	s, ok := overflow.Add64(a, b)
	if !ok {
		panic("zdex: add overflow")
	}
	return s
}

// AmountOut is Uniswap-v2 getAmountOut against effective (real+virtual) reserves.
// Payout is capped by the real reserveOut — virtual offsets only affect price.
func AmountOut(amountIn, reserveIn, virtualIn, reserveOut, virtualOut, feeBps int64) int64 {
	if amountIn <= 0 {
		panic("zdex: amountIn must be positive")
	}
	if feeBps < 0 || feeBps >= bpsDen {
		panic("zdex: feeBps out of range")
	}
	x := add64(reserveIn, virtualIn)
	y := add64(reserveOut, virtualOut)
	if x <= 0 || y <= 0 {
		panic("zdex: empty effective reserves")
	}
	fee := MulDiv(amountIn, feeBps, bpsDen)
	net := amountIn - fee
	if net <= 0 {
		panic("zdex: fee consumes input")
	}
	out := MulDiv(net, y, add64(x, net))
	if out <= 0 {
		panic("zdex: zero output")
	}
	if out >= y {
		panic("zdex: would drain effective reserve")
	}
	if out >= reserveOut {
		panic("zdex: insufficient real reserve")
	}
	return out
}

// AmountIn is the ugnot/token that must be paid so AmountOut >= amountOut.
// Rounded up so ExactOut does not underpay.
func AmountIn(amountOut, reserveIn, virtualIn, reserveOut, virtualOut, feeBps int64) int64 {
	if amountOut <= 0 {
		panic("zdex: amountOut must be positive")
	}
	if feeBps < 0 || feeBps >= bpsDen {
		panic("zdex: feeBps out of range")
	}
	if amountOut >= reserveOut {
		panic("zdex: insufficient real reserve")
	}
	x := add64(reserveIn, virtualIn)
	y := add64(reserveOut, virtualOut)
	if x <= 0 || y <= 0 {
		panic("zdex: empty effective reserves")
	}
	if amountOut >= y {
		panic("zdex: would drain effective reserve")
	}
	net := MulDivCeil(amountOut, x, y-amountOut)
	in := MulDivCeil(net, bpsDen, bpsDen-feeBps)
	if in <= 0 {
		panic("zdex: zero input")
	}
	got := AmountOut(in, reserveIn, virtualIn, reserveOut, virtualOut, feeBps)
	if got < amountOut {
		in = add64(in, 1)
	}
	return in
}

package zdex

import "chain"

func SetPaused(cur realm, v bool) {
	mustOwner(cur)
	paused = v
	chain.Emit("Pause", "paused", itoa(btoi(v)))
}

func ProposeAdmin(cur realm, next address) {
	mustOwner(cur)
	require(next.IsValid(), "zdex: invalid admin")
	pendingAdmin = next
	chain.Emit("ProposeAdmin", "to", next.String())
}

func AcceptAdmin(cur realm) {
	require(pendingAdmin.IsValid(), "zdex: no pending admin")
	require(cur.Previous().Address() == pendingAdmin, "zdex: not pending admin")
	admin = pendingAdmin
	var z address
	pendingAdmin = z
	chain.Emit("AcceptAdmin", "to", admin.String())
}

func TransferAdmin(cur realm, next address) {
	ProposeAdmin(cur, next)
}

func Admin() address {
	return admin
}

func RealmAddr() address {
	return thisAddr()
}

func PendingAdmin() address {
	return pendingAdmin
}

func Paused() bool {
	return paused
}

func CollectFees(cur realm, poolID string) (ugnotOut, tokenOut int64) {
	p := getPool(poolID)
	caller := cur.Previous().Address()
	got := false
	if caller == p.Creator {
		ugnotOut = add64(ugnotOut, p.AccruedCreatorU)
		tokenOut = add64(tokenOut, p.AccruedCreatorT)
		p.AccruedCreatorU = 0
		p.AccruedCreatorT = 0
		got = true
	}
	if caller == admin {
		ugnotOut = add64(ugnotOut, p.AccruedProtocolU)
		tokenOut = add64(tokenOut, p.AccruedProtocolT)
		p.AccruedProtocolU = 0
		p.AccruedProtocolT = 0
		got = true
	}
	require(got, "zdex: not fee recipient")
	require(ugnotOut > 0 || tokenOut > 0, "zdex: nothing accrued")
	if ugnotOut > 0 {
		sendUgnot(0, cur, caller, ugnotOut)
	}
	if tokenOut > 0 {
		pushToken(0, cur, poolTokRef(p), caller, tokenOut)
	}
	chain.Emit("CollectFees", "pool", poolID, "to", caller.String(), "ugnot", itoa(ugnotOut), "token", itoa(tokenOut))
	return ugnotOut, tokenOut
}

func btoi(v bool) int64 {
	if v {
		return 1
	}
	return 0
}

package zdex

import "chain"

// PlaceBid escrows ugnot (OriginSend) for `wantAmt` of the pool token at a
// fixed limit. Partial fills keep the original ratio. expireH=0 means never.
func PlaceBid(cur realm, poolID string, giveU, wantAmt, expireH int64, allOrNone bool) uint64 {
	assertNotPaused()
	require(giveU > 0 && wantAmt > 0, "zdex: amounts")
	_ = getPool(poolID)
	if expireH > 0 {
		require(expireH > height(), "zdex: already expired")
	}
	takeUgnot(cur, giveU)
	id := uint64(nextOrd.Next())
	orders.Set(itoa(int64(id)), &Order{
		ID:        id,
		Maker:     cur.Previous().Address(),
		PoolID:    poolID,
		GiveUgnot: true,
		GiveAmt:   giveU,
		WantAmt:   wantAmt,
		ExpireH:   expireH,
		AllOrNone: allOrNone,
	})
	chain.Emit("PlaceBid", "id", itoa(int64(id)), "pool", poolID, "give", itoa(giveU), "want", itoa(wantAmt))
	return id
}

// PlaceAsk escrows the pool token, wanting ugnot.
func PlaceAsk(cur realm, poolID string, giveT, wantU, expireH int64, allOrNone bool) uint64 {
	assertNotPaused()
	require(giveT > 0 && wantU > 0, "zdex: amounts")
	p := getPool(poolID)
	if expireH > 0 {
		require(expireH > height(), "zdex: already expired")
	}
	caller := cur.Previous().Address()
	pullUserToken(0, cur, poolTokRef(p), caller, giveT)
	id := uint64(nextOrd.Next())
	orders.Set(itoa(int64(id)), &Order{
		ID:        id,
		Maker:     caller,
		PoolID:    poolID,
		GiveUgnot: false,
		GiveAmt:   giveT,
		WantAmt:   wantU,
		ExpireH:   expireH,
		AllOrNone: allOrNone,
	})
	chain.Emit("PlaceAsk", "id", itoa(int64(id)), "pool", poolID, "give", itoa(giveT), "want", itoa(wantU))
	return id
}

// FillOrder lets a taker take up to `giveAmt` of what they pay.
// Bids: taker pays token (pulled), receives ugnot.
// Asks: taker pays ugnot (OriginSend), receives token.
func FillOrder(cur realm, orderID uint64, giveAmt int64) (paid, received int64) {
	assertNotPaused()
	require(giveAmt > 0, "zdex: giveAmt")
	o := getOrder(orderID)
	require(o.GiveAmt > 0, "zdex: filled")
	if o.ExpireH > 0 {
		require(height() <= o.ExpireH, "zdex: expired")
	}
	p := getPool(o.PoolID)
	taker := cur.Previous().Address()

	if o.GiveUgnot {
		// Bid: taker sells token, receives ugnot.
		// fill fraction of remaining want.
		wantTake := giveAmt
		if wantTake > o.WantAmt {
			wantTake = o.WantAmt
		}
		if o.AllOrNone {
			require(wantTake == o.WantAmt, "zdex: all-or-none")
		}
		payU := MulDiv(o.GiveAmt, wantTake, o.WantAmt)
		require(payU > 0, "zdex: dust")
		if payU > o.GiveAmt {
			payU = o.GiveAmt
		}
		pullUserToken(0, cur, poolTokRef(p), taker, wantTake)
		sendUgnot(0, cur, taker, payU)
		pushToken(0, cur, poolTokRef(p), o.Maker, wantTake)
		o.GiveAmt -= payU
		o.WantAmt -= wantTake
		paid, received = wantTake, payU
	} else {
		// Ask: taker pays ugnot, receives token.
		takeU := giveAmt
		if takeU > o.WantAmt {
			takeU = o.WantAmt
		}
		if o.AllOrNone {
			require(takeU == o.WantAmt, "zdex: all-or-none")
		}
		takeUgnot(cur, takeU)
		payT := MulDiv(o.GiveAmt, takeU, o.WantAmt)
		require(payT > 0, "zdex: dust")
		if payT > o.GiveAmt {
			payT = o.GiveAmt
		}
		sendUgnot(0, cur, o.Maker, takeU)
		pushToken(0, cur, poolTokRef(p), taker, payT)
		o.GiveAmt -= payT
		o.WantAmt -= takeU
		paid, received = takeU, payT
	}

	settleFill(0, cur, o, p)
	chain.Emit("FillOrder", "id", itoa(int64(o.ID)), "taker", taker.String(), "paid", itoa(paid), "received", itoa(received))
	return paid, received
}

func settleFill(_ int, rlm realm, o *Order, p *Pool) {
	if o.GiveAmt != 0 && o.WantAmt != 0 {
		return
	}
	if o.GiveAmt > 0 && o.WantAmt == 0 {
		if o.GiveUgnot {
			sendUgnot(0, rlm, o.Maker, o.GiveAmt)
		} else {
			pushToken(0, rlm, poolTokRef(p), o.Maker, o.GiveAmt)
		}
	}
	orders.Remove(itoa(int64(o.ID)))
}

func CancelOrder(cur realm, orderID uint64) {
	o := getOrder(orderID)
	require(o.Maker == cur.Previous().Address(), "zdex: not maker")
	p := getPool(o.PoolID)
	if o.GiveUgnot {
		sendUgnot(0, cur, o.Maker, o.GiveAmt)
	} else {
		pushToken(0, cur, poolTokRef(p), o.Maker, o.GiveAmt)
	}
	orders.Remove(itoa(int64(o.ID)))
	chain.Emit("CancelOrder", "id", itoa(int64(o.ID)))
}

func getOrder(id uint64) *Order {
	v := orders.Get(itoa(int64(id)))
	require(v != nil, "zdex: order not found")
	return v.(*Order)
}

func OrderCount() int {
	return orders.Size()
}

package zdex

import "chain"

// Launch is a legacy bonding-curve minter. zdex product surface is DEX-only
// (CreatePool + swap + LP). Keep this entry so already-launched pools still
// trade; do not expose it in UI or gnoweb.
func Launch(cur realm, name, symbol string, decimals, totalSupply, creatorKeepBps, virtualUgnot, vestBlocks, lockBlocks, snipeBlocks, snipeMaxBps int64) string {
	assertNotPaused()
	require(cur.Previous().IsUserCall(), "zdex: EOA only")
	require(totalSupply > minLiquidity, "zdex: supply too small")
	require(virtualUgnot > 0, "zdex: virtualUgnot")
	require(creatorKeepBps >= 0 && creatorKeepBps <= maxCreatorKeepBps, "zdex: creator keep")
	require(decimals >= 0 && decimals <= 18, "zdex: decimals")
	require(tryPool(poolIDFor(symbol)) == nil, "zdex: pool exists")

	if creatorKeepBps > 0 && vestBlocks < minVestBlocks {
		vestBlocks = minVestBlocks
	}
	if lockBlocks < minLockBlocks {
		lockBlocks = minLockBlocks
	}
	if snipeBlocks <= 0 {
		snipeBlocks = defaultSnipeBlocks
	}
	if snipeMaxBps <= 0 {
		snipeMaxBps = defaultSnipeMaxBps
	}
	require(snipeMaxBps <= maxSnipeMaxBps, "zdex: snipe max")

	creator := cur.Previous().Address()
	keep := MulDiv(totalSupply, creatorKeepBps, bpsDen)
	poolAmt := totalSupply - keep
	require(poolAmt > minLiquidity, "zdex: pool seed too small")

	key := mintInternal(cur, name, symbol, decimals, totalSupply, cur.Address())

	h := height()
	if keep > 0 {
		vests.Set(vestKey(symbol, creator), &Vesting{
			Symbol: symbol,
			Owner:  creator,
			Total:  keep,
			StartH: h,
			EndH:   h + vestBlocks,
		})
	}

	id := poolIDFor(symbol)
	// Burned (unowned) LP so TotalLP > 0: after unlock, others can add.
	// Nobody holds a Position for this seed, so it cannot be withdrawn.
	lp := geoMean(virtualUgnot, poolAmt)
	require(lp > minLiquidity, "zdex: tiny launch LP")
	p := &Pool{
		ID:           id,
		Token:        key,
		Symbol:       symbol,
		Name:         name,
		ReserveU:     0,
		ReserveT:     poolAmt,
		VirtualU:     virtualUgnot,
		TotalLP:      lp,
		FeeBps:       launchFeeBps,
		Creator:      creator,
		CreatorBps:   launchCreatorFeeBps,
		ProtocolBps:  launchProtocolFeeBps,
		Decimals:     decimals,
		UnlockHeight: h + lockBlocks,
		SnipeUntil:   h + snipeBlocks,
		SnipeMaxBps:  snipeMaxBps,
		Launched:     true,
		Internal:     true,
	}
	pools.Set(id, p)

	chain.Emit("Launch",
		"pool", id,
		"symbol", symbol,
		"token", key,
		"supply", itoa(totalSupply),
		"keep", itoa(keep),
		"virtual", itoa(virtualUgnot),
		"lp", itoa(lp),
		"creator", creator.String(),
	)
	return id
}

// ClaimVest releases linearly vested creator tokens.
func ClaimVest(cur realm, symbol string) int64 {
	assertNotPaused()
	owner := cur.Previous().Address()
	v := vests.Get(vestKey(symbol, owner))
	require(v != nil, "zdex: no vesting")
	vs := v.(*Vesting)
	rel := vestedAmount(vs, height())
	delta := rel - vs.Claimed
	require(delta > 0, "zdex: nothing to claim")
	vs.Claimed = rel
	pushToken(0, cur, symbol, owner, delta)
	chain.Emit("ClaimVest", "symbol", symbol, "to", owner.String(), "amount", itoa(delta))
	return delta
}

func vestedAmount(vs *Vesting, h int64) int64 {
	if h <= vs.StartH {
		return 0
	}
	if vs.EndH <= vs.StartH || h >= vs.EndH {
		return vs.Total
	}
	return MulDiv(vs.Total, h-vs.StartH, vs.EndH-vs.StartH)
}

func VestingOf(symbol string, owner address) (total, claimed, releasable int64) {
	v := vests.Get(vestKey(symbol, owner))
	if v == nil {
		return 0, 0, 0
	}
	vs := v.(*Vesting)
	rel := vestedAmount(vs, height())
	return vs.Total, vs.Claimed, rel - vs.Claimed
}

package zdex

import (
	"math/overflow"

	"gno.land/p/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/zdex/amm/v1"
)

// AMM formula lives in gno.land/p/<g1>/zdex/amm/v1 on Pearl (namespace
// "zdex" is not authorized). Local source still imports gno.land/p/zdex/amm/v1.
// ship without touching LP, book, or points in this realm. These wrappers
// keep the v1 MsgCall/qeval names stable.

func MulDiv(a, b, d int64) int64 {
	return amm.MulDiv(a, b, d)
}

func Sqrt(n int64) int64 {
	return amm.Sqrt(n)
}

func MulDivCeil(a, b, d int64) int64 {
	return amm.MulDivCeil(a, b, d)
}

func AmountOut(amountIn, reserveIn, virtualIn, reserveOut, virtualOut, feeBps int64) int64 {
	return amm.AmountOut(amountIn, reserveIn, virtualIn, reserveOut, virtualOut, feeBps)
}

func AmountIn(amountOut, reserveIn, virtualIn, reserveOut, virtualOut, feeBps int64) int64 {
	return amm.AmountIn(amountOut, reserveIn, virtualIn, reserveOut, virtualOut, feeBps)
}

func geoMean(a, b int64) int64 {
	prod, ok := overflow.Mul64(a, b)
	if ok {
		return Sqrt(prod)
	}
	return MulDiv(Sqrt(a), Sqrt(b), 1)
}

func min64(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func add64(a, b int64) int64 {
	s, ok := overflow.Add64(a, b)
	if !ok {
		panic("zdex: add overflow")
	}
	return s
}

func sub64(a, b int64) int64 {
	if b > a {
		panic("zdex: sub underflow")
	}
	return a - b
}

type feeSplit struct {
	gross    int64
	net      int64
	lp       int64
	creator  int64
	protocol int64
}

func splitFee(amountIn, feeBps, creatorBps, protocolBps int64) feeSplit {
	if feeBps < 0 || feeBps >= 10000 {
		panic("zdex: feeBps out of range")
	}
	if creatorBps < 0 || protocolBps < 0 || creatorBps+protocolBps > 10000 {
		panic("zdex: fee share out of range")
	}
	fee := MulDiv(amountIn, feeBps, 10000)
	net := amountIn - fee
	creator := MulDiv(fee, creatorBps, 10000)
	protocol := MulDiv(fee, protocolBps, 10000)
	lp := fee - creator - protocol
	if lp < 0 {
		panic("zdex: fee split underflow")
	}
	return feeSplit{gross: amountIn, net: net, lp: lp, creator: creator, protocol: protocol}
}

package zdex

import "chain"

func maybeRollEpoch() {
	h := height()
	if epochBlocks <= 0 {
		epochBlocks = defaultEpochBlocks
	}
	if epoch == 0 {
		epoch = 1
		epochEnd = h + epochBlocks
		return
	}
	if h < epochEnd {
		return
	}
	carry := closedPot
	closedID = epoch
	closedPts = epochPts
	closedPot = epochPot
	epoch++
	epochPts = 0
	epochPot = carry
	epochEnd = h + epochBlocks
	chain.Emit("Epoch", "id", itoa(int64(epoch)), "closedPot", itoa(closedPot), "closedPts", itoa(closedPts))
}

func getScore(owner address) *Score {
	v := scores.Get(owner.String())
	if v == nil {
		s := &Score{}
		scores.Set(owner.String(), s)
		return s
	}
	return v.(*Score)
}

func syncScore(s *Score) {
	maybeRollEpoch()
	if s.EpochID == epoch {
		return
	}
	if s.EpochID == closedID {
		s.Closed = s.Epoch
	} else {
		s.Closed = 0
	}
	s.Epoch = 0
	s.EpochID = epoch
}

func addPoints(owner address, pts int64) {
	if pts <= 0 {
		return
	}
	maybeRollEpoch()
	s := getScore(owner)
	syncScore(s)
	s.Epoch = add64(s.Epoch, pts)
	s.Life = add64(s.Life, pts)
	epochPts = add64(epochPts, pts)
}

func harvestLP(p *Pool, owner address) {
	st := getPos(p.ID, owner)
	if st == nil || st.LP <= 0 {
		return
	}
	acc := MulDiv(st.LP, p.AccPoints, ptsScale)
	if acc > st.RewardDebt {
		addPoints(owner, acc-st.RewardDebt)
	}
	st.RewardDebt = acc
}

func creditSwapPoints(p *Pool, trader address, volU int64, fs feeSplit, ugnotSide bool) {
	maybeRollEpoch()
	if ugnotSide {
		p.AccruedCreatorU = add64(p.AccruedCreatorU, fs.creator)
		if fs.protocol > 0 {
			if feeShareBps <= 0 {
				feeShareBps = defaultFeeShareBps
			}
			toUsers := MulDiv(fs.protocol, feeShareBps, bpsDen)
			p.AccruedProtocolU = add64(p.AccruedProtocolU, fs.protocol-toUsers)
			epochPot = add64(epochPot, toUsers)
		}
	} else {
		p.AccruedCreatorT = add64(p.AccruedCreatorT, fs.creator)
		p.AccruedProtocolT = add64(p.AccruedProtocolT, fs.protocol)
	}
	if volU <= 0 {
		return
	}
	addPoints(trader, volU)
	if p.TotalLP > 0 {
		p.AccPoints = add64(p.AccPoints, MulDiv(volU, ptsScale, p.TotalLP))
	}
}

// HarvestPoints settles LP points for a pool without depositing. No extra stake.
func HarvestPoints(cur realm, poolID string) int64 {
	assertNotPaused()
	p := getPool(poolID)
	owner := cur.Previous().Address()
	before := getScore(owner).Life
	harvestLP(p, owner)
	return getScore(owner).Life - before
}

// ClaimFeeShare pays last closed epoch's protocol-ugnot pot, pro-rata by points.
func ClaimFeeShare(cur realm) int64 {
	maybeRollEpoch()
	require(closedID > 0 && closedPot > 0 && closedPts > 0, "zdex: nothing to share")
	owner := cur.Previous().Address()
	s := getScore(owner)
	syncScore(s)
	require(s.ClaimedID != closedID, "zdex: already claimed")
	require(s.Closed > 0, "zdex: no epoch points")
	out := MulDiv(s.Closed, closedPot, closedPts)
	require(out > 0, "zdex: share too small")
	s.ClaimedID = closedID
	closedPot = sub64(closedPot, out)
	closedPts = sub64(closedPts, s.Closed)
	sendUgnot(0, cur, owner, out)
	chain.Emit("ClaimFeeShare", "to", owner.String(), "ugnot", itoa(out), "epoch", itoa(int64(closedID)))
	return out
}

func PointsOf(owner address) (life, epochPtsUser, closedPtsUser int64) {
	v := scores.Get(owner.String())
	if v == nil {
		return 0, 0, 0
	}
	s := v.(*Score)
	if s.EpochID == epoch {
		return s.Life, s.Epoch, s.Closed
	}
	if s.EpochID == closedID {
		return s.Life, 0, s.Epoch
	}
	return s.Life, 0, 0
}

func ClaimableFeeShare(owner address) int64 {
	if closedID == 0 || closedPot <= 0 || closedPts <= 0 {
		return 0
	}
	v := scores.Get(owner.String())
	if v == nil {
		return 0
	}
	s := v.(*Score)
	if s.ClaimedID == closedID {
		return 0
	}
	closed := s.Closed
	if s.EpochID == closedID {
		closed = s.Epoch
	} else if s.EpochID != epoch {
		return 0
	}
	return MulDiv(closed, closedPot, closedPts)
}

func EpochInfo() (id, endH, pot, pts, cID, cPot, cPts int64) {
	return int64(epoch), epochEnd, epochPot, epochPts, int64(closedID), closedPot, closedPts
}

func SetEpochBlocks(cur realm, n int64) {
	mustOwner(cur)
	require(n >= 10, "zdex: epoch too short")
	epochBlocks = n
	h := height()
	if epoch > 0 && epochEnd > h+n {
		epochEnd = h + n
	}
}

func SetFeeShareBps(cur realm, bps int64) {
	mustOwner(cur)
	require(bps >= 0 && bps <= bpsDen, "zdex: fee share")
	feeShareBps = bps
}

package zdex

import (
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/demo/defi/grc20reg"
)

// Height is the current chain height (for UI deadlines).
func Height() int64 {
	return height()
}

// PoolList returns one pool id per line.
func PoolList() string {
	out := ""
	pools.Iterate("", "", func(k string, _ any) bool {
		if out != "" {
			out += "\n"
		}
		out += k
		return false
	})
	return out
}

// PoolSnapshot is a single-line UI record:
// id;symbol;name;reserveU;reserveT;virtualU;totalLP;feeBps;launched;unlockH;snipeUntil;snipeMaxBps;creator;decimals
func PoolSnapshot(poolID string) string {
	p := getPool(poolID)
	return ufmt.Sprintf("%s;%s;%s;%d;%d;%d;%d;%d;%d;%d;%d;%d;%s;%d",
		p.ID, p.Symbol, p.Name,
		p.ReserveU, p.ReserveT, p.VirtualU, p.TotalLP, p.FeeBps,
		btoi(p.Launched), p.UnlockHeight, p.SnipeUntil, p.SnipeMaxBps,
		p.Creator.String(), p.Decimals)
}

// OrderList returns one order per line:
// id;pool;side;giveAmt;wantAmt;expireH;allOrNone;maker
func OrderList() string {
	out := ""
	orders.Iterate("", "", func(_ string, v any) bool {
		o := v.(*Order)
		side := "ask"
		if o.GiveUgnot {
			side = "bid"
		}
		line := ufmt.Sprintf("%d;%s;%s;%d;%d;%d;%d;%s",
			int64(o.ID), o.PoolID, side, o.GiveAmt, o.WantAmt, o.ExpireH, btoi(o.AllOrNone), o.Maker.String())
		if out != "" {
			out += "\n"
		}
		out += line
		return false
	})
	return out
}

func PointsSnapshot(owner address) string {
	life, ep, cl := PointsOf(owner)
	return ufmt.Sprintf("%d;%d;%d;%d", life, ep, cl, ClaimableFeeShare(owner))
}

func EpochSnapshot() string {
	id, endH, pot, pts, cID, cPot, cPts := EpochInfo()
	return ufmt.Sprintf("%d;%d;%d;%d;%d;%d;%d", id, endH, pot, pts, cID, cPot, cPts)
}

func tokenLine(symbol, name, key string, decimals int64, pooled, internal bool) string {
	if name == "" {
		name = symbol
	}
	return ufmt.Sprintf("%s;%s;%s;%d;%d;%d", symbol, name, key, decimals, btoi(pooled), btoi(internal))
}

// TokenCatalog lists known tokens (internal + pooled), one per line:
// symbol;name;key;decimals;pooled;internal
func TokenCatalog() string {
	out := ""
	seen := map[string]bool{}
	add := func(line, symbol string) {
		if seen[symbol] {
			return
		}
		seen[symbol] = true
		if out != "" {
			out += "\n"
		}
		out += line
	}
	tokens.Iterate("", "", func(k string, v any) bool {
		rec := v.(*tokenRec)
		pooled := tryPool(poolIDFor(k)) != nil
		add(tokenLine(rec.token.GetSymbol(), rec.token.GetName(), rec.token.ID(), int64(rec.token.GetDecimals()), pooled, true), k)
		return false
	})
	pools.Iterate("", "", func(_ string, v any) bool {
		p := v.(*Pool)
		internal := tryTok(p.Symbol) != nil
		add(tokenLine(p.Symbol, p.Name, p.Token, p.Decimals, true, internal), p.Symbol)
		return false
	})
	return out
}

// LookupToken resolves an internal symbol, pool id, or GRC20 registry key.
// Same record as TokenCatalog, or empty if unknown.
func LookupToken(ref string) string {
	if ref == "" {
		return ""
	}
	if p := tryPool(ref); p != nil {
		return tokenLine(p.Symbol, p.Name, p.Token, p.Decimals, true, tryTok(p.Symbol) != nil)
	}
	if rec := tryTok(ref); rec != nil {
		return tokenLine(rec.token.GetSymbol(), rec.token.GetName(), rec.token.ID(), int64(rec.token.GetDecimals()), tryPool(poolIDFor(ref)) != nil, true)
	}
	if p := tryPool(poolIDFor(ref)); p != nil {
		return tokenLine(p.Symbol, p.Name, p.Token, p.Decimals, true, tryTok(p.Symbol) != nil)
	}
	t := grc20reg.Get(ref)
	if t == nil {
		return ""
	}
	sym := t.GetSymbol()
	return tokenLine(sym, t.GetName(), ref, int64(t.GetDecimals()), tryPool(poolIDFor(sym)) != nil, false)
}

package zdex

import (
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
)

func Render(path string) string {
	switch path {
	case "", "home":
		return renderHome()
	case "book":
		return renderBook()
	default:
		if len(path) > 5 && path[:5] == "pool/" {
			return renderPool(path[5:])
		}
		if len(path) > 6 && path[:6] == "token/" {
			return renderToken(path[6:])
		}
		return "> [!WARNING]\n> Path not found.\n"
	}
}

func renderHome() string {
	out := "# zdex v2\n\n"
	out += "GNOT-native AMM generation 2. Two-sided pools, native `ugnot` (no wrap), escrow limit orders.\n"
	out += "Swap fee 0.30% default (tiers 0.05% / 0.30% / 1.00%). Protocol ~1/6 of the fee.\n\n"
	if paused {
		out += "> [!CAUTION]\n> Protocol is paused.\n\n"
	}
	out += ufmt.Sprintf("* Version: **%s**\n* Package: `%s`\n", Version(), thisPkg())
	if nextPkg != "" {
		out += ufmt.Sprintf("* Next: `%s`\n", sanitize.InlineText(nextPkg))
	}
	out += ufmt.Sprintf("* Pools: **%d**\n* Open orders: **%d**\n* Admin: `%s`\n\n",
		pools.Size(), orders.Size(), admin.String())

	out += "## Pools\n\n"
	if pools.Size() == 0 {
		out += "_None yet. Create a two-sided pool._\n\n"
	} else {
		out += "| Pair | ugnot | token | virtual | fee | launch |\n|---|---:|---:|---:|---:|---|\n"
		pools.Iterate("", "", func(_ string, v any) bool {
			p := v.(*Pool)
			out += ufmt.Sprintf("| [%s](pool/%s) | %d | %d | %d | %d bps | %s |\n",
				sanitize.InlineText(p.Symbol), p.ID, p.ReserveU, p.ReserveT, p.VirtualU, p.FeeBps, yesno(p.Launched))
			return false
		})
		out += "\n"
	}

	out += "## Swap\n\n"
	out += "<gno-form exec=\"SwapExactIn\">\n"
	out += "<gno-input name=\"poolID\" placeholder=\"ugnot|SYMBOL\" required=\"true\" />\n"
	out += "<gno-input name=\"tokenIn\" placeholder=\"ugnot or SYMBOL\" required=\"true\" />\n"
	out += "<gno-input name=\"amountIn\" type=\"number\" placeholder=\"amount in\" required=\"true\" />\n"
	out += "<gno-input name=\"minOut\" type=\"number\" placeholder=\"min out\" required=\"true\" />\n"
	out += "<gno-input name=\"maxHeight\" type=\"number\" placeholder=\"deadline height (0=none)\" />\n"
	out += "</gno-form>\n\n"

	out += "## Create a pool\n\n"
	out += "Two-sided ugnot/GRC20. Min **1 GNOT**. Fee tiers 5 / 30 / 100 bps. Protocol takes ~1/6 of the swap fee; the rest stays as LP.\n\n"
	out += "<gno-form exec=\"CreatePool\">\n"
	out += "<gno-input name=\"tokenKey\" placeholder=\"GRC20 registry key\" required=\"true\" />\n"
	out += "<gno-input name=\"symbol\" placeholder=\"SYMBOL\" required=\"true\" />\n"
	out += "<gno-input name=\"amountU\" type=\"number\" placeholder=\"ugnot (>= 1000000)\" required=\"true\" />\n"
	out += "<gno-input name=\"amountT\" type=\"number\" placeholder=\"token amount\" required=\"true\" />\n"
	out += "<gno-input name=\"feeBps\" type=\"number\" placeholder=\"30 = 0.30%\" required=\"true\" />\n"
	out += "</gno-form>\n\n"

	out += "[Order book](book)\n"
	return out
}

func renderPool(id string) string {
	id = sanitize.InlineText(id)
	p := tryPool(id)
	if p == nil {
		return "> [!WARNING]\n> Pool not found.\n"
	}
	out := ufmt.Sprintf("# Pool %s\n\n", sanitize.InlineText(p.Symbol))
	out += ufmt.Sprintf("* Token: `%s`\n* Real ugnot: **%d**\n* Real token: **%d**\n* Virtual ugnot: **%d**\n",
		p.Token, p.ReserveU, p.ReserveT, p.VirtualU)
	out += ufmt.Sprintf("* Fee: %d bps (creator share %d, protocol %d)\n* LP: %d\n* Unlock height: %d (now %d)\n",
		p.FeeBps, p.CreatorBps, p.ProtocolBps, p.TotalLP, p.UnlockHeight, height())
	if p.SnipeUntil > height() {
		out += ufmt.Sprintf("* Snipe cap: %d bps until height %d\n", p.SnipeMaxBps, p.SnipeUntil)
	}
	out += "\n## Swap on this pool\n\n"
	out += "<gno-form exec=\"SwapExactIn\">\n"
	out += ufmt.Sprintf("<gno-input name=\"poolID\" value=\"%s\" required=\"true\" />\n", p.ID)
	out += "<gno-input name=\"tokenIn\" placeholder=\"ugnot or symbol\" required=\"true\" />\n"
	out += "<gno-input name=\"amountIn\" type=\"number\" required=\"true\" />\n"
	out += "<gno-input name=\"minOut\" type=\"number\" required=\"true\" />\n"
	out += "<gno-input name=\"maxHeight\" type=\"number\" />\n"
	out += "</gno-form>\n"
	return out
}

func renderToken(symbol string) string {
	symbol = sanitize.InlineText(symbol)
	rec := tryTok(symbol)
	out := ufmt.Sprintf("# %s\n\n", symbol)
	if rec != nil {
		out += rec.token.RenderHome() + "\n"
	}
	p := tryPool(poolIDFor(symbol))
	if p != nil {
		out += ufmt.Sprintf("[Open pool](pool/%s)\n", p.ID)
	}
	return out
}

func renderBook() string {
	out := "# Order book\n\n"
	if orders.Size() == 0 {
		out += "_No resting orders._\n\n"
	} else {
		out += "| id | side | pool | give | want | maker |\n|---:|---|---|---:|---:|---|\n"
		orders.Iterate("", "", func(_ string, v any) bool {
			o := v.(*Order)
			side := "ask"
			if o.GiveUgnot {
				side = "bid"
			}
			out += ufmt.Sprintf("| %d | %s | %s | %d | %d | `%s` |\n",
				o.ID, side, o.PoolID, o.GiveAmt, o.WantAmt, o.Maker.String())
			return false
		})
		out += "\n"
	}
	out += "## Place bid (pay ugnot, receive token)\n\n"
	out += "<gno-form exec=\"PlaceBid\">\n"
	out += "<gno-input name=\"poolID\" required=\"true\" />\n"
	out += "<gno-input name=\"giveU\" type=\"number\" placeholder=\"ugnot escrowed\" required=\"true\" />\n"
	out += "<gno-input name=\"wantAmt\" type=\"number\" placeholder=\"tokens wanted\" required=\"true\" />\n"
	out += "<gno-input name=\"expireH\" type=\"number\" placeholder=\"0 = never\" />\n"
	out += "<gno-input name=\"allOrNone\" placeholder=\"false\" />\n"
	out += "</gno-form>\n\n"
	out += "## Place ask (pay token, receive ugnot)\n\n"
	out += "<gno-form exec=\"PlaceAsk\">\n"
	out += "<gno-input name=\"poolID\" required=\"true\" />\n"
	out += "<gno-input name=\"giveT\" type=\"number\" placeholder=\"token escrowed\" required=\"true\" />\n"
	out += "<gno-input name=\"wantU\" type=\"number\" placeholder=\"ugnot wanted\" required=\"true\" />\n"
	out += "<gno-input name=\"expireH\" type=\"number\" />\n"
	out += "<gno-input name=\"allOrNone\" placeholder=\"false\" />\n"
	out += "</gno-form>\n"
	return out
}

func yesno(v bool) string {
	if v {
		return "yes"
	}
	return "no"
}

package zdex

import (
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

var (
	admin        address
	pendingAdmin address
	paused       bool
	pools        avl.Tree
	pos     avl.Tree
	orders  avl.Tree
	vests   avl.Tree
	tokens  avl.Tree
	scores  avl.Tree
	modules avl.Tree // surface name -> pkg path; empty means this hub
	nextOrd seqid.ID

	epoch        uint64
	epochEnd     int64
	epochPts     int64
	epochPot     int64
	epochBlocks  int64
	feeShareBps  int64
	closedID     uint64
	closedPts    int64
	closedPot    int64
)

func init(cur realm) {
	admin = cur.Previous().Address()
	epochBlocks = defaultEpochBlocks
	feeShareBps = defaultFeeShareBps
}

func thisAddr() address {
	return unsafe.CurrentRealm().Address()
}

func thisPkg() string {
	return unsafe.CurrentRealm().PkgPath()
}

func height() int64 {
	return runtime.ChainHeight()
}

func mustOwner(cur realm) {
	if cur.Previous().Address() != admin {
		panic("zdex: admin only")
	}
}

func assertNotPaused() {
	if paused {
		panic("zdex: paused")
	}
}

func poolIDFor(symbol string) string {
	return nativeDenom + "|" + symbol
}

func posKey(poolID string, owner address) string {
	return poolID + "/" + owner.String()
}

func vestKey(symbol string, owner address) string {
	return symbol + "/" + owner.String()
}

func getPool(id string) *Pool {
	v := pools.Get(id)
	if v == nil {
		panic("zdex: pool not found")
	}
	return v.(*Pool)
}

func tryPool(id string) *Pool {
	v := pools.Get(id)
	if v == nil {
		return nil
	}
	return v.(*Pool)
}

func getPos(poolID string, owner address) *Position {
	v := pos.Get(posKey(poolID, owner))
	if v == nil {
		return nil
	}
	return v.(*Position)
}

func setPos(poolID string, owner address, lp int64) {
	k := posKey(poolID, owner)
	if lp == 0 {
		pos.Remove(k)
		return
	}
	pos.Set(k, &Position{LP: lp})
}

func require(cond bool, msg string) {
	if !cond {
		panic(msg)
	}
}

func checkErr(err error) {
	if err != nil {
		panic(err.Error())
	}
}

package zdex

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
)

// Quote returns the token/ugnot the trader would receive for amountIn.
// tokenIn is "ugnot" or the pool symbol (or registry key).
func Quote(poolID, tokenIn string, amountIn int64) int64 {
	p := getPool(poolID)
	buy := tokenIn == nativeDenom
	if buy {
		return AmountOut(amountIn, p.ReserveU, p.VirtualU, p.ReserveT, 0, p.FeeBps)
	}
	return AmountOut(amountIn, p.ReserveT, 0, p.ReserveU, 0, p.FeeBps)
}

// QuoteIn returns the input needed so the trader receives at least amountOut
// of tokenOut ("ugnot" or the pool symbol).
func QuoteIn(poolID, tokenOut string, amountOut int64) int64 {
	p := getPool(poolID)
	if tokenOut == nativeDenom {
		return AmountIn(amountOut, p.ReserveT, 0, p.ReserveU, 0, p.FeeBps)
	}
	return AmountIn(amountOut, p.ReserveU, p.VirtualU, p.ReserveT, 0, p.FeeBps)
}

func assertDeadline(maxHeight int64) {
	if maxHeight > 0 {
		require(height() <= maxHeight, "zdex: expired")
	}
}

func assertSnipe(p *Pool, out int64, buy bool) {
	if height() >= p.SnipeUntil || p.SnipeMaxBps <= 0 {
		return
	}
	base := p.ReserveU
	if buy {
		base = p.ReserveT
	}
	capOut := MulDiv(base, p.SnipeMaxBps, bpsDen)
	require(out <= capOut, "zdex: snipe cap")
}

func creditFees(p *Pool, fs feeSplit, ugnotSide bool) {
	if ugnotSide {
		p.AccruedCreatorU = add64(p.AccruedCreatorU, fs.creator)
		p.AccruedProtocolU = add64(p.AccruedProtocolU, fs.protocol)
	} else {
		p.AccruedCreatorT = add64(p.AccruedCreatorT, fs.creator)
		p.AccruedProtocolT = add64(p.AccruedProtocolT, fs.protocol)
	}
}

func emitSwap(p *Pool, trader address, tokenIn string, amountIn, amountOut, fee int64) {
	chain.Emit("Swap",
		"pool", p.ID,
		"trader", trader.String(),
		"tokenIn", tokenIn,
		"amountIn", itoa(amountIn),
		"amountOut", itoa(amountOut),
		"reserveU", itoa(p.ReserveU),
		"reserveT", itoa(p.ReserveT),
		"fee", itoa(fee),
	)
}

// SwapExactIn executes a swap against a ugnot/token pool.
// tokenIn is "ugnot" (pay with OriginSend) or the pool symbol/key.
// minOut is slippage protection; maxHeight is a deadline (0 = none).
func SwapExactIn(cur realm, poolID, tokenIn string, amountIn, minOut, maxHeight int64) int64 {
	assertNotPaused()
	require(amountIn > 0, "zdex: amountIn")
	require(minOut >= 0, "zdex: minOut")
	assertDeadline(maxHeight)

	p := getPool(poolID)
	buy := tokenIn == nativeDenom
	caller := cur.Previous().Address()

	var out int64
	if buy {
		require(cur.Previous().IsUserCall(), "zdex: ugnot swap is EOA-only")
		sent := unsafe.OriginSend().AmountOf(nativeDenom)
		require(sent == amountIn, "zdex: OriginSend mismatch")
		out = AmountOut(amountIn, p.ReserveU, p.VirtualU, p.ReserveT, 0, p.FeeBps)
		require(out >= minOut, "zdex: slippage")
		assertSnipe(p, out, true)
		fs := splitFee(amountIn, p.FeeBps, p.CreatorBps, p.ProtocolBps)
		p.ReserveU = add64(p.ReserveU, fs.net+fs.lp)
		creditSwapPoints(p, caller, amountIn, fs, true)
		p.ReserveT = sub64(p.ReserveT, out)
		maybeGraduate(p)
		pushToken(0, cur, poolTokRef(p), caller, out)
		emitSwap(p, caller, tokenIn, amountIn, out, fs.gross-fs.net)
	} else {
		require(tokenIn == p.Symbol || tokenIn == p.Token, "zdex: tokenIn")
		out = AmountOut(amountIn, p.ReserveT, 0, p.ReserveU, 0, p.FeeBps)
		require(out >= minOut, "zdex: slippage")
		assertSnipe(p, out, false)
		pullUserToken(0, cur, poolTokRef(p), caller, amountIn)
		fs := splitFee(amountIn, p.FeeBps, p.CreatorBps, p.ProtocolBps)
		p.ReserveT = add64(p.ReserveT, fs.net+fs.lp)
		creditSwapPoints(p, caller, out, fs, false)
		p.ReserveU = sub64(p.ReserveU, out)
		sendUgnot(0, cur, caller, out)
		emitSwap(p, caller, tokenIn, amountIn, out, fs.gross-fs.net)
	}
	return out
}

// SwapExactOut pays as little as needed to receive amountOut of tokenOut.
// tokenOut is "ugnot" or the pool symbol. maxIn caps what the trader pays.
// Buying tokens: send at least the required ugnot; excess is refunded.
func SwapExactOut(cur realm, poolID, tokenOut string, amountOut, maxIn, maxHeight int64) int64 {
	assertNotPaused()
	require(amountOut > 0, "zdex: amountOut")
	require(maxIn > 0, "zdex: maxIn")
	assertDeadline(maxHeight)

	p := getPool(poolID)
	caller := cur.Previous().Address()
	buy := tokenOut != nativeDenom && tokenOut != ""

	if buy {
		require(tokenOut == p.Symbol || tokenOut == p.Token, "zdex: tokenOut")
		require(cur.Previous().IsUserCall(), "zdex: ugnot swap is EOA-only")
		in := AmountIn(amountOut, p.ReserveU, p.VirtualU, p.ReserveT, 0, p.FeeBps)
		require(in <= maxIn, "zdex: slippage")
		sent := unsafe.OriginSend().AmountOf(nativeDenom)
		require(sent >= in, "zdex: OriginSend mismatch")
		assertSnipe(p, amountOut, true)
		fs := splitFee(in, p.FeeBps, p.CreatorBps, p.ProtocolBps)
		p.ReserveU = add64(p.ReserveU, fs.net+fs.lp)
		creditSwapPoints(p, caller, in, fs, true)
		p.ReserveT = sub64(p.ReserveT, amountOut)
		maybeGraduate(p)
		pushToken(0, cur, poolTokRef(p), caller, amountOut)
		if sent > in {
			sendUgnot(0, cur, caller, sent-in)
		}
		emitSwap(p, caller, nativeDenom, in, amountOut, fs.gross-fs.net)
		return in
	}

	in := AmountIn(amountOut, p.ReserveT, 0, p.ReserveU, 0, p.FeeBps)
	require(in <= maxIn, "zdex: slippage")
	assertSnipe(p, amountOut, false)
	pullUserToken(0, cur, poolTokRef(p), caller, in)
	fs := splitFee(in, p.FeeBps, p.CreatorBps, p.ProtocolBps)
	p.ReserveT = add64(p.ReserveT, fs.net+fs.lp)
	creditSwapPoints(p, caller, amountOut, fs, false)
	p.ReserveU = sub64(p.ReserveU, amountOut)
	sendUgnot(0, cur, caller, amountOut)
	emitSwap(p, caller, p.Symbol, in, amountOut, fs.gross-fs.net)
	return in
}

func maybeGraduate(p *Pool) {
	if p.VirtualU <= 0 || p.ReserveU < p.VirtualU {
		return
	}
	p.VirtualU = 0
	chain.Emit("Graduate", "pool", p.ID, "reserveU", itoa(p.ReserveU))
}

func SpotPrice(poolID string) int64 {
	p := getPool(poolID)
	den := add64(p.ReserveU, p.VirtualU)
	if den <= 0 || p.ReserveT <= 0 {
		return 0
	}
	return MulDiv(p.ReserveT, 1_000_000, den)
}

func sendUgnot(_ int, rlm realm, to address, amount int64) {
	if !rlm.IsCurrent() {
		panic("zdex: spoofed realm")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	bk.SendCoins(rlm.Address(), to, chain.Coins{{Denom: nativeDenom, Amount: amount}})
}

func takeUgnot(cur realm, amount int64) {
	require(cur.Previous().IsUserCall(), "zdex: ugnot is EOA-only")
	sent := unsafe.OriginSend().AmountOf(nativeDenom)
	require(sent == amount, "zdex: OriginSend mismatch")
}

package zdex

import (
	"gno.land/p/demo/tokens/grc20"
	"gno.land/p/nt/seqid/v0"
	"gno.land/r/demo/defi/grc20reg"
)

type tokenRec struct {
	token  *grc20.Token
	ledger *grc20.PrivateLedger
}

var nextTok seqid.ID

func getTok(symbol string) *tokenRec {
	v := tokens.Get(symbol)
	if v == nil {
		panic("zdex: unknown token " + symbol)
	}
	return v.(*tokenRec)
}

func tryTok(symbol string) *tokenRec {
	v := tokens.Get(symbol)
	if v == nil {
		return nil
	}
	return v.(*tokenRec)
}

func mintInternal(cur realm, name, symbol string, decimals, amount int64, to address) string {
	require(tryTok(symbol) == nil, "zdex: symbol taken")
	require(decimals >= 0 && decimals <= 18, "zdex: decimals")
	tok, led := grc20.NewToken(name, symbol, int(decimals), nextTok.Next(), cur)
	if amount > 0 {
		checkErr(led.Mint(to, amount))
	}
	tokens.Set(symbol, &tokenRec{token: tok, ledger: led})
	return grc20reg.Register(cross(cur), tok, "")
}

func tokenPullKey(tokenKey, symbol string) string {
	if tryTok(symbol) != nil {
		return symbol
	}
	if tokenKey != "" {
		return tokenKey
	}
	return symbol
}

func poolTokRef(p *Pool) string {
	if p.Internal || p.Token == "" {
		return p.Symbol
	}
	return p.Token
}

func pullUserToken(_ int, rlm realm, symbol string, from address, amount int64) {
	require(amount > 0, "zdex: amount")
	if !rlm.IsCurrent() {
		panic("zdex: spoofed realm")
	}
	require(from == rlm.Previous().Address(), "zdex: from must be caller")
	rec := tryTok(symbol)
	if rec != nil {
		checkErr(rec.ledger.CallerTeller().Transfer(0, rlm, thisAddr(), amount))
		return
	}
	// Pearl grc20reg write wrappers are non-crossing: rlm must be this
	// realm's live cur. cross() would debit the registry instead.
	grc20reg.TransferFrom(0, rlm, symbol, from, thisAddr(), amount)
}

func pushToken(_ int, rlm realm, symbol string, to address, amount int64) {
	require(amount > 0, "zdex: amount")
	if !rlm.IsCurrent() {
		panic("zdex: spoofed realm")
	}
	rec := tryTok(symbol)
	if rec != nil {
		checkErr(rec.ledger.Transfer(thisAddr(), to, amount))
		return
	}
	grc20reg.Transfer(0, rlm, symbol, to, amount)
}

func tokenBalance(symbol string, owner address) int64 {
	rec := tryTok(symbol)
	if rec != nil {
		return rec.token.BalanceOf(owner)
	}
	t := grc20reg.Get(symbol)
	if t == nil {
		return 0
	}
	return t.BalanceOf(owner)
}

// Transfer moves an internally minted token. External GRC20s are transferred
// on their own realm.
func Transfer(cur realm, symbol string, to address, amount int64) {
	rec := getTok(symbol)
	checkErr(rec.ledger.CallerTeller().Transfer(0, cur, to, amount))
}

func Approve(cur realm, symbol string, spender address, amount int64) {
	rec := getTok(symbol)
	checkErr(rec.ledger.CallerTeller().Approve(0, cur, spender, amount))
}

func TransferFrom(cur realm, symbol string, from, to address, amount int64) {
	rec := getTok(symbol)
	checkErr(rec.ledger.CallerTeller().TransferFrom(0, cur, from, to, amount))
}

func BalanceOf(symbol string, owner address) int64 {
	return tokenBalance(symbol, owner)
}

func TotalSupply(symbol string) int64 {
	rec := tryTok(symbol)
	if rec == nil {
		t := grc20reg.Get(symbol)
		if t == nil {
			return 0
		}
		return t.TotalSupply()
	}
	return rec.token.TotalSupply()
}

func TokenKey(symbol string) string {
	rec := tryTok(symbol)
	if rec == nil {
		return ""
	}
	return rec.token.ID()
}

package zdex

import (
	"chain"

	"gno.land/p/nt/ufmt/v0"
)

// protoVersion is this realm generation. Gno packages are immutable:
// v2 is this path. A later /v3 ships as a new package; LP here stays.
// Admin points NextPkg / SetModule at the successor.
const protoVersion = "2"

const (
	modSwap   = "swap"
	modLP     = "lp"
	modCreate = "create"
	modBook   = "book"
	modPoints = "points"
	modQuote  = "quote"
	modAdmin  = "admin"
)

const defaultCaps = "swap;lp;create;book;points;quote;feeShare;noStakeLp"

var nextPkg string

func validModule(name string) bool {
	return name == modSwap || name == modLP || name == modCreate ||
		name == modBook || name == modPoints || name == modQuote || name == modAdmin
}

func moduleNames() []string {
	return []string{modSwap, modLP, modCreate, modBook, modPoints, modQuote, modAdmin}
}

// Version is the ABI generation of this hub. v1 freeze: SwapExactIn,
// AddLiquidity, CreatePool, book, and points keep their names.
func Version() string {
	return protoVersion
}

// Caps is a semicolon-separated capability list so UIs feature-gate
// without coupling to a package path. Missing Caps on an older realm
// means the client should fall back to probing individual queries.
func Caps() string {
	return defaultCaps
}

// ThisPkg is the path of this hub realm.
func ThisPkg() string {
	return thisPkg()
}

// NextPkg is empty until admin points this generation at a successor.
// Liquidity and open orders stay in this package; the UI may switch
// new flow to NextPkg without rewriting swap/LP/points clients.
func NextPkg() string {
	return nextPkg
}

func SetNextPkg(cur realm, path string) {
	mustOwner(cur)
	nextPkg = path
	chain.Emit("NextPkg", "path", path)
}

// ModuleOf returns the package that currently owns a surface.
// Unmapped names resolve to this hub so a v2 book can move alone.
func ModuleOf(name string) string {
	if !validModule(name) {
		return thisPkg()
	}
	v := modules.Get(name)
	if v == nil {
		return thisPkg()
	}
	s, ok := v.(string)
	if !ok || s == "" {
		return thisPkg()
	}
	return s
}

func SetModule(cur realm, name, pkg string) {
	mustOwner(cur)
	require(validModule(name), "zdex: unknown module")
	if pkg == "" {
		modules.Remove(name)
	} else {
		modules.Set(name, pkg)
	}
	chain.Emit("SetModule", "name", name, "pkg", pkg)
}

// Modules is one surface per line: name;pkg
func Modules() string {
	out := ""
	for _, n := range moduleNames() {
		line := n + ";" + ModuleOf(n)
		if out != "" {
			out += "\n"
		}
		out += line
	}
	return out
}

// HubSnapshot is a single-line UI record:
// version;thisPkg;nextPkg;caps  (caps may contain further semicolons)
func HubSnapshot() string {
	return ufmt.Sprintf("%s;%s;%s;%s", Version(), thisPkg(), nextPkg, Caps())
}

